class MenuRepository extends \Doctrine\ORM\EntityRepository {

    public function query_menu($priviliges) {//$role, $rolecourants
        
        $qb = $this->createQueryBuilder('m');
       $i=0;
        foreach($priviliges as $values){
            
           $qb->orWhere("UPPER(m.typecompte) LIKE :role".$i)  
              ->setParameter("role".$i,"%" . strtoupper($values) . "%");
           $i++;
        }
       /* foreach ($priviliges as $key => $values) {
           
          $qb->orWhere("UPPER(m.typecompte) LIKE :role" . $key)  
             ->setParameter("role" . $key, "%" . strtoupper($values) . "%");
               
        } */
      
  /* ->where("UPPER(m.typecompte) LIKE :role ")
                ->setParameter("role", "%" . strtoupper($role) . "%");
        foreach ($rolecourants as $key => $rolecourant) {
            $qb->orWhere("UPPER(m.typecompte) LIKE :role" . $key)
                 ->setParameter("role" . $key, "%" . strtoupper($rolecourant) . "%");
        }
*/
        //$qb->groupBy("m.typecompte");
        $qb->andWhere("m.actifMenu = 0");
        
        $qb->orderBy("m.ordre", "ASC");
        
        //var_dump($role);
        //var_dump($qb->getQuery()); die;
       // var_dump($qb->getParameters()); die;
        return $qb->getQuery()->getResult();
    }

  public function tableau_bord($role, $mois, $annee){
 
  switch($role){
       case "ROLE_Charge_etudes": {
           
         $qb = $this->getEntityManager()->createQueryBuilder()
                    ->from('EdiligenceBundle:Tcourrier','c')
                    ->select('count(c.id)')
                    ->Where("Year(c.dateCreat)=:annee")
                    ->andWhere("Month(c.dateCreat)=:mois")
                    ->setParameter('annee', $annee)
                    ->setParameter('mois',  $mois);
         //dump($qb->getQuery());die;
         $result = $qb->getQuery()->getSingleScalarResult();   
       } break; 
       default:{
             $qb = $this->getEntityManager()->createQueryBuilder()
                    ->from('EdiligenceBundle:Tcourrier','c')
                    ->select('count(c.id)')
                    ->Where("Year(c.dateCreat)=:annee")
                    ->andWhere("Month(c.dateCreat)=:mois")
                    ->setParameter('annee', $annee)
                    ->setParameter('mois',  $mois);
         //dump($qb->getQuery());die;
         $result = $qb->getQuery()->getSingleScalarResult();   
       }
 

      } 
      return $result;
  }
 
  
  
}
